System.register([],function(e,i){return{setters:[],execute:function(){e("SCRIPT_CONFIG",{id:"order-disorder",title:"Order and Disorder",category:"pattern",description:"A rotating influence field pulls a grid of points between ordered and chaotic states, driven by Perlin noise.",version:"1.1.0",canvas:{width:1080,height:1080,context:"p5"},compute:{cost:"particle"},parameters:[{group:"Grid",params:[{key:"gridSpacing",type:"slider",label:"Grid Spacing",min:2,max:30,step:1,default:6},{key:"gridMargin",type:"slider",label:"Grid Margin",min:0,max:80,step:2,default:10},{key:"pointSize",type:"slider",label:"Point Size",min:1,max:8,step:.5,default:2}]},{group:"Noise",params:[{key:"noiseMaxOffset",type:"slider",label:"Noise Offset",min:0,max:60,step:1,default:20},{key:"noiseSpatialScale",type:"slider",label:"Noise Spatial Scale",min:.005,max:.15,step:.005,default:.03},{key:"noiseTimeScale",type:"slider",label:"Noise Time Scale",min:.001,max:.05,step:.001,default:.016},{key:"jiggleAmount",type:"slider",label:"Jiggle Amount",min:0,max:10,step:.5,default:2},{key:"jiggleSpeed",type:"slider",label:"Jiggle Speed",min:.01,max:.5,step:.01,default:.15}]},{group:"Influence",params:[{key:"sourceRadius",type:"slider",label:"Source Radius",min:50,max:500,step:10,default:270},{key:"innerConstraint",type:"slider",label:"Inner Constraint",min:50,max:400,step:10,default:195},{key:"outerConstraint",type:"slider",label:"Outer Constraint",min:50,max:400,step:10,default:165},{key:"cwConstraint",type:"slider",label:"CW Constraint (°)",min:10,max:120,step:5,default:40},{key:"ccwConstraint",type:"slider",label:"CCW Constraint (°)",min:10,max:120,step:5,default:70},{key:"blendFactor",type:"slider",label:"Blend Factor",min:0,max:1,step:.05,default:.8},{key:"innerRatio",type:"slider",label:"Inner Ratio",min:0,max:1,step:.05,default:.4}]},{group:"Animation",params:[{key:"loopFrames",type:"slider",label:"Loop Frames",min:60,max:720,step:60,default:360}]}],presets:[{name:"Classic",values:{gridSpacing:6,gridMargin:10,pointSize:2,noiseMaxOffset:20,noiseSpatialScale:.03,noiseTimeScale:.016,jiggleAmount:2,jiggleSpeed:.15,sourceRadius:270,innerConstraint:195,outerConstraint:165,cwConstraint:40,ccwConstraint:70,blendFactor:.8,innerRatio:.4,loopFrames:360}},{name:"Dense",values:{gridSpacing:3,gridMargin:5,pointSize:1,noiseMaxOffset:15,noiseSpatialScale:.04,noiseTimeScale:.02,jiggleAmount:3,jiggleSpeed:.2,sourceRadius:300,innerConstraint:200,outerConstraint:150,cwConstraint:50,ccwConstraint:80,blendFactor:.7,innerRatio:.35,loopFrames:360}},{name:"Wide Chaos",values:{gridSpacing:8,gridMargin:10,pointSize:3,noiseMaxOffset:40,noiseSpatialScale:.025,noiseTimeScale:.01,jiggleAmount:5,jiggleSpeed:.1,sourceRadius:350,innerConstraint:250,outerConstraint:200,cwConstraint:60,ccwConstraint:90,blendFactor:.85,innerRatio:.5,loopFrames:720}}],export:{png:!0,gif:!1,webm:!1},animation:{type:"infinite",defaultFps:60,animatableParams:["noiseMaxOffset","noiseSpatialScale","noiseTimeScale","jiggleAmount","pointSize"],sequencer:!0},infoSections:[{heading:"DESCRIPTION",body:"Order and Disorder renders a rectangular grid of points on a 1080×1080 canvas. A rotating asymmetric bean-shaped influence zone sweeps continuously around the canvas centre. Points inside the zone are pulled toward their home grid positions (ordered state). Points outside the zone drift under Perlin noise displacement (disordered state). Points at the zone boundary receive additional jiggle noise proportional to their proximity to the transition edge. The influence zone completes one orbit in loopFrames frames. Noise time advances monotonically and does not cycle, so the disordered field evolves continuously without repeating."},{heading:"ALGORITHM",body:"Grid: points at integer multiples of gridSpacing, inset by gridMargin from each canvas edge. Each point stores its home position (gridX, gridY) and three unique Perlin seed offsets (noiseOffsetX, noiseOffsetY, jiggleOffset). Influence field: sourceTheta = 2π × (frame % loopFrames) / loopFrames. Per-point alpha: dx = px − W/2, dy = py − H/2; currentR = ‖(dx,dy)‖; rawDiffR = currentR − sourceRadius; normR = rawDiffR≥0 ? rawDiffR/outerConstraint : |rawDiffR|/innerConstraint. rawDiffTheta = normalise(atan2(dy,dx) − sourceTheta) ∈ (−π,π]; effectiveR = (1−blendFactor)×sourceRadius + blendFactor×currentR; arcCW = sourceRadius×cwConstraint×π/180; arcCCW = sourceRadius×ccwConstraint×π/180; currentArc = |rawDiffTheta|×effectiveR; normTheta = currentArc/arcCW (CW) or /arcCCW (CCW); curve = 1 (CW) or 0.7 (CCW); curvedR = clamp(normR,0,1)^1; curvedTheta = clamp(normTheta,0,1)^curve; d = ‖(curvedR,curvedTheta)‖; alpha = 1 if d≤innerRatio, else clamp(1−(d−innerRatio)/(1−innerRatio),0,1). Displacement: t = frame×noiseTimeScale; noiseX/Y = (p.noise(spatialCoord+offset, t)−0.5)×2; noisyPos = gridPos + noise×noiseMaxOffset; basePos = lerp(noisyPos, gridPos, alpha). Jiggle: jt = frame×jiggleSpeed; transitionAmt = 1−|alpha−0.5|×2; jx/jy = (p.noise(jiggleOffset±500, jt)−0.5)×2×jiggleAmount×transitionAmt. Draw: p.beginShape(POINTS); p.vertex(baseX+jx, baseY+jy) per point; p.endShape()."},{heading:"PARAMETERS",body:"Grid — gridSpacing: slider 2–30 step 1 default 6; pixel gap between adjacent grid points, controls density. Rebuilds point array on change. gridMargin: slider 0–80 step 2 default 10; inset in pixels from each canvas edge. Rebuilds point array on change. pointSize: slider 1–8 step 0.5 default 2; strokeWeight for each rendered point. Noise — noiseMaxOffset: slider 0–60 step 1 default 20; maximum pixel displacement applied in the disorder zone. noiseSpatialScale: slider 0.005–0.15 step 0.005 default 0.03; spatial frequency of the Perlin field; lower = smoother broad flows, higher = fine granular displacement. noiseTimeScale: slider 0.001–0.05 step 0.001 default 0.016; rate of noise time advance per frame; controls how fast the disorder field evolves. jiggleAmount: slider 0–10 step 0.5 default 2; maximum jiggle displacement applied at the zone boundary (alpha ≈ 0.5). jiggleSpeed: slider 0.01–0.5 step 0.01 default 0.15; rate of jiggle noise time advance per frame. Influence — sourceRadius: slider 50–500 step 10 default 270; orbital radius of the influence source from the canvas centre. innerConstraint: slider 50–400 step 10 default 195; radial falloff distance (pixels) for points closer to centre than sourceRadius. outerConstraint: slider 50–400 step 10 default 165; radial falloff distance for points further from centre than sourceRadius. cwConstraint: slider 10–120 step 5 default 40; angular arc limit in degrees on the clockwise side; smaller = narrower CW edge. ccwConstraint: slider 10–120 step 5 default 70; angular arc limit in degrees on the counter-clockwise side; larger than CW produces the bean asymmetry. blendFactor: slider 0–1 step 0.05 default 0.8; 0 measures angular arc at sourceRadius; 1 measures at the actual point radius; controls how the bean shape changes at different radii. innerRatio: slider 0–1 step 0.05 default 0.4; fraction of combined distance d below which alpha is forced to 1 (solid ordered core). Animation — loopFrames: slider 60–720 step 60 default 360; number of frames per influence-zone orbit; controls rotation speed, not a true noise loop boundary."},{heading:"PRESETS",body:"Classic — gridSpacing 6, gridMargin 10, pointSize 2, loopFrames 360, noiseMaxOffset 20, sourceRadius 270. Balanced default: moderate grid density with a clear ordered island surrounded by a disordered field; gentle boundary jiggle. Dense — gridSpacing 3, gridMargin 5, pointSize 1, loopFrames 360, noiseSpatialScale 0.04, noiseTimeScale 0.02. Fine-grain grid (~177² ≈ 31K points at gridSpacing 6 vs ~353² ≈ 125K at gridSpacing 3 with gridMargin 5); faster, finer noise evolution; narrower inner zone (innerRatio 0.35). Significantly higher per-frame compute cost than Classic. Wide Chaos — gridSpacing 8, gridMargin 10, pointSize 3, loopFrames 720, noiseMaxOffset 40, jiggleAmount 5, sourceRadius 350, cwConstraint 60, ccwConstraint 90. Wider disorder zone and larger influence orbit; slow noise time (0.01); long rotation period (720 frames = 12 s at 60 FPS); coarse grid with large visible displacement."},{heading:"PERFORMANCE",body:"Point count N = ceil((canvasWidth − 2×gridMargin) / gridSpacing)². At gridSpacing 30 (lowest density): ~37² ≈ 1,369 points. At default gridSpacing 6: ~177² ≈ 31,329 points. At gridSpacing 2, gridMargin 0 (maximum density): ~540² ≈ 291,600 points. Per-frame cost: one pass over all N points. Per point: _getAlpha (1 sqrt, 1 atan2, ~15 arithmetic ops), 3 Perlin noise lookups (3D each, ~30–50 ops apiece), 1 vertex call. Dominant bottleneck: ~94,000 Perlin noise evaluations/frame at default settings; ~875,000 at maximum density — well above the 16ms budget. Avoid gridSpacing 2 during 60 FPS animation. Point rendering uses p.beginShape(POINTS)/p.endShape() to batch all vertex calls into one canvas path operation instead of N individual p.point calls, reducing canvas API overhead. Grid rebuild on gridSpacing or gridMargin change allocates N objects; moderate GC pressure at high N. Worker offload is not feasible: p.noise() and p.vertex() require the P5 instance. Tier 2 adaptive resolution does not reduce point count (grid is spacing-based, not pixel-based) and is therefore not applied."},{heading:"ANIMATION",body:"Type: infinite — the animation runs continuously without a defined terminal frame. The influence zone rotation is controlled by loopFrames: sourceTheta = 2π × (frame % loopFrames) / loopFrames, completing one orbit every loopFrames frames and producing a visually periodic rotation. Noise time t = frame × noiseTimeScale advances monotonically without modulo; the noise displacement field evolves continuously and never reproduces its earlier state. Animation is therefore non-loopable: there is no frame offset at which the canvas returns to its initial appearance. Default FPS: 60. Export: PNG only. GIF and WebM are disabled — a clean loop capture requires the noise field to return to its initial state, which would require a 4D noise-loop technique (embedding time as an angular parameter in a higher-dimensional Perlin space)."},{heading:"KNOWN LIMITATIONS",body:"Noise is non-loopable: t = frame × noiseTimeScale and jt = frame × jiggleSpeed both advance without modulo. A GIF export would show a visible discontinuity at any wrap boundary and is disabled. The influence zone rotation IS periodic (period = loopFrames frames), but the noise displacement state differs at every frame, making seamless loop export infeasible without a fundamentally different noise model. At minimum gridSpacing (2) and gridMargin (0), N ≈ 291,600 points; per-frame time will significantly exceed 16ms on most hardware. The radialCurve exponent for the CW boundary is hardcoded to 1 (linear falloff); the CCW boundary uses 0.7 (softer). Exposing radialCurve as a user slider would give symmetric control over both boundary sharpnesses. loopFrames in the Animation group controls the rotation period, not a true animation loop; this naming is retained for consistency with the influence field description but does not imply a loop boundary for export."},{heading:"REFERENCES",body:"Origin: port of order_and_disorder sketch. No legacy specification; Phase 3 source-only analysis. Alpha field: combined radial and angular normalised distance in a 2D constraint space (curvedR, curvedTheta); analogous to a polar SDF with asymmetric angular falloff and an ellipsoidal core threshold. Perlin noise: p5.js built-in p.noise(), 3D gradient noise. Lerp-toward-grid displacement: standard particle anchor technique weighted by the alpha field."}],_points:null,_lastParams:null,_needsRebuild(e){return!this._lastParams||this._lastParams.gridSpacing!==e.gridSpacing||this._lastParams.gridMargin!==e.gridMargin},_buildPoints(e,i,a){const{gridSpacing:t,gridMargin:n}=e,r=[];let o=0;for(let s=n;s<=a-n;s+=t)for(let e=n;e<=i-n;e+=t)r.push({gridX:e,gridY:s,index:o++,noiseOffsetX:.1*o,noiseOffsetY:.1*o+1e3,jiggleOffset:.1*o+2e3});return r},_normalizeAngle(e){for(;e>Math.PI;)e-=2*Math.PI;for(;e<-Math.PI;)e+=2*Math.PI;return e},_getAlpha(e,i,a,t,n,r){const{sourceRadius:o,innerConstraint:s,outerConstraint:l,cwConstraint:d,ccwConstraint:p,blendFactor:c,innerRatio:u}=r,g=e-a,f=i-t,m=Math.sqrt(g*g+f*f),h=Math.atan2(f,g),b=m-o,y=b>=0?b/l:Math.abs(b)/s,S=this._normalizeAngle(h-n),w=(1-c)*o+c*m,C=o*(d*Math.PI/180),v=o*(p*Math.PI/180),x=Math.abs(S)*w,M=S>=0?x/C:x/v,R=S>=0?1:.7,P=Math.pow(Math.min(1,Math.max(0,y)),1),A=Math.pow(Math.min(1,Math.max(0,M)),R),F=Math.sqrt(P*P+A*A);if(F<=u)return 1;const T=(F-u)/(1-u);return Math.min(1,Math.max(0,1-T))},p5Setup(e,i){e.noLoop(),e.noSmooth(),this._points=this._buildPoints(i,e.width,e.height),this._lastParams={...i}},p5Draw(e,i,a){this._needsRebuild(i)&&(this._points=this._buildPoints(i,e.width,e.height),this._lastParams={...i}),e.background(255),e.stroke(0),e.strokeWeight(i.pointSize);const t=e.width/2,n=e.height/2,{loopFrames:r,noiseMaxOffset:o,noiseSpatialScale:s,noiseTimeScale:l,jiggleAmount:d,jiggleSpeed:p}=i,c=2*Math.PI*(a%r)/r,u=a*l,g=a*p;e.beginShape(e.POINTS);for(const f of this._points){const a=this._getAlpha(f.gridX,f.gridY,t,n,c,i),r=f.gridX*s,l=f.gridY*s,p=2*(e.noise(r+f.noiseOffsetX,l,u)-.5),m=2*(e.noise(r,l+f.noiseOffsetY,u)-.5),h=f.gridX+p*o,b=f.gridY+m*o,y=h+(f.gridX-h)*a,S=b+(f.gridY-b)*a,w=1-2*Math.abs(a-.5),C=2*(e.noise(f.jiggleOffset,g)-.5)*d*w,v=2*(e.noise(f.jiggleOffset+500,g)-.5)*d*w;e.vertex(y+C,S+v)}e.endShape()}})}}});